flow-diagram.createChart:
{
n = 200;
hdr = list(reactFlowGanttRow(model: "hdr", label: reactFlowText("Month", fontWeight: "bold"), acceptsDrop: false, backgroundColor: "#e3eaf1", minContentHeight: 16));
rows = count(0, $n).map(i -> reactFlowGanttRow(model: $i, label: reactFlowPadding(left: ($i % 4) * 14, content: reactFlowText("Work package " + $i + " with a longer name", fontSize: 12)), borderColor: "#e4e8ec", rowPadding: 3, minContentHeight: 18));
months = count(0, 24).map(m -> reactFlowGanttSpan(model: list("m", $m), rowModel: "hdr", start: $m * 30, end: $m * 30 + 30, canMove: false, canResize: false, canBeEdge: false,
  box: reactFlowBorder(top: false, bottom: false, right: false, stroke: "#9aa7b4", content: reactFlowText("M" + $m, fontSize: 11))));
bars = count(0, $n).map(i -> reactFlowGanttSpan(model: list("b", $i), rowModel: $i, start: ($i * 3) % 500, end: ($i * 3) % 500 + 120, canBeEdge: false,
  box: reactFlowPadding(top: 6, bottom: 6, content: reactFlowFill(fill: "#73B1DD", content: reactFlowEmpty(minHeight: 6)))));
diamond = c -> reactFlowPadding(top: 2, content: reactFlowPolygon(points: list(reactFlowPoint(0, 7), reactFlowPoint(7, 0), reactFlowPoint(14, 7), reactFlowPoint(7, 14)), fillStyle: $c, stroke: "#222"));
pts = count(0, $n).flatMap(i -> count(0, 3).map(k -> reactFlowGanttPoint(model: list("p", $i, $k), rowModel: $i, at: ($i * 3) % 500 + $k * 60, canMoveRow: false, canBeEdge: false,
  box: reactFlowTooltip(text: "Milestone " + $i + "/" + $k, content: $diamond(if($k == 1, "#FFD400", "#1f5fa8"))))));
edges = count(1, $n).map(i -> reactFlowGanttEdge(model: list("e", $i), sourceModel: list("p", $i - 1, 2), sourceEndpoint: "END", targetModel: list("p", $i, 0), targetEndpoint: "START",
  strokeColor: "#222", strokeWidth: 1, violatedStrokeColor: "#e00000", targetSymbol: "filledArrow"));
reactFlowChart(
  fixedView: true,
  root: reactFlowVertical(gap: 8, contents: list(
    reactFlowPadding(all: 8, content: reactFlowVertical(gap: 4, contents: list(
      reactFlowText("Release schedule: 200 work packages", fontSize: 16, fontWeight: "bold"),
      reactFlowText("Drag a bar or milestone to move it, drag the end of a bar to resize it, Ctrl+wheel zooms the time axis.", fontSize: 12)))),
    reactFlowGantt(rootRows: list($hdr, $rows).flatten(), items: list($months, $bars, $pts).flatten(), edges: $edges,
      decorations: list(reactFlowGanttLineDeco(model: "today", at: 250, color: "#FFC800", strokeWidth: 2,
        label: reactFlowFill(fill: "#FFC800", content: reactFlowPadding(all: 2, content: reactFlowText("Today", fontSize: 11))))),
      rangeMin: 0, rangeMax: 720, frozenRows: 1))));
}
